// All x <= X with x and x+1 both S-smooth, for an explicit prime set S (complete for the given X:
// every S-smooth number <= X+1 is generated by DFS, sorted, and consecutive members reported).
// Usage: ./sunit_pairs X q1 q2 ... qk     (prints x, one per line; stats on stderr)
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
typedef unsigned __int128 u128;
static uint64_t *A; static size_t n, cap; static uint64_t X1; static uint64_t P[256]; static int k;
static void push(uint64_t v){ if(n==cap){cap=cap?cap*2:1<<20; A=realloc(A,cap*8); if(!A){fprintf(stderr,"oom\n");exit(1);} } A[n++]=v; }
static void dfs(int i, uint64_t v){            // v times products of P[i..k-1]
  if(i==k){ push(v); return; }
  for(u128 w=v; w<=X1; w*=P[i]) dfs(i+1,(uint64_t)w);
}
static int cmp(const void*a,const void*b){ uint64_t x=*(uint64_t*)a,y=*(uint64_t*)b; return x<y?-1:x>y; }
int main(int argc,char**argv){
  X1 = strtoull(argv[1],0,10) + 1; k = argc-2;
  for(int i=0;i<k;i++) P[i]=strtoull(argv[i+2],0,10);
  // sort primes descending: big primes first keeps the DFS tree narrow at the top
  for(int i=0;i<k;i++) for(int j=i+1;j<k;j++) if(P[j]>P[i]){uint64_t t=P[i];P[i]=P[j];P[j]=t;}
  dfs(0,1);
  qsort(A,n,8,cmp);
  size_t pairs=0;
  for(size_t i=0;i+1<n;i++) if(A[i+1]==A[i]+1 && A[i]+1<=X1){ printf("%llu\n",(unsigned long long)A[i]); pairs++; }
  fprintf(stderr,"S-smooth <= %llu: %zu ; consecutive pairs: %zu\n",(unsigned long long)X1,n,pairs);
  return 0;
}
